CREATE TABLE IF NOT EXISTS meeting_inbox (id TEXT PRIMARY KEY, connection_id TEXT NOT NULL, title TEXT NOT NULL, mime_type TEXT NOT NULL, modified_at TEXT NOT NULL, detected_at TEXT NOT NULL, source_email TEXT NOT NULL, held_at TEXT, state TEXT NOT NULL DEFAULT 'unlinked', customer_id TEXT, appointment_id TEXT, analysis TEXT, customer_version INTEGER, appointment_version INTEGER, version INTEGER NOT NULL DEFAULT 1, lease_until TEXT, confirmed_by TEXT, confirmed_at TEXT);
